// Get a starting face that is guaranteed to be exterior
// (typically outside the bounding box of the triangulation)
Triangulation::Face_handle start_face = nullptr;

// Find a face on the convex hull or use an infinite face
for (Triangulation::All_faces_iterator it = triangulation.all_faces_begin();
     it != triangulation.all_faces_end(); ++it) {
    // Check if this face has at least one infinite vertex or is on the boundary
    if (triangulation.is_infinite(it)) {
        start_face = it;
        break;
    }
}

// If no infinite face found, try to find a face on the convex hull
if (!start_face) {
    for (Triangulation::Finite_faces_iterator it = triangulation.finite_faces_begin();
         it != triangulation.finite_faces_end(); ++it) {
        for (int i = 0; i < 3; i++) {
            if (triangulation.is_constrained(typename Triangulation::Edge(it, i))) {
                start_face = it;
                break;
            }
        }
        if (start_face) break;
    }
}

